-- apply-cb-tags.sql — Inserts reconciled CB corpus tags into cb_question_sub_skills, cb_question_clusters, cb_distractor_clusters.
-- Generated 2026-11-22. NOT for direct application — Karl applies.
-- Taxonomy version: scl-v1.0.0
-- Source: 6-pass consensus (1 write + 5 blind audits), ≥4/6 majority or write-pass tiebreaker.
BEGIN;


-- Sanity checks
SELECT 'sub_skills' AS tag_type, count(*) AS total FROM public.cb_question_sub_skills WHERE taxonomy_version = 'scl-v1.0.0'
UNION ALL
SELECT 'clusters', count(*) FROM public.cb_question_clusters WHERE taxonomy_version = 'scl-v1.0.0'
UNION ALL
SELECT 'distractors', count(*) FROM public.cb_distractor_clusters WHERE taxonomy_version = 'scl-v1.0.0';

COMMIT;
